228→	if err != nil {
229→		t.Fatal(err)
230→	}
231→	if !slices.Equal(files, want.files) || current != want.position {
232→		t.Errorf("files/current = %v/%d, want %v/%d", files, current, want.files, want.position)
233→	}
234→	prompts, err := agent.ExtractPrompts(path, 0)
235→	if err != nil {
236→		t.Fatal(err)
237→	}
238→	if !slices.Equal(prompts, want.prompts) {
239→		t.Errorf("prompts = %v, want %v", prompts, want.prompts)
240→	}
241→	summary, ok, err := agent.ExtractSummary(path)
242→	if err != nil {
243→		t.Fatal(err)
244→	}
245→	if !ok || summary != want.summary {
246→		t.Errorf("summary = %q/%v, want %q/true", summary, ok, want.summary)
247→	}
