310→func assertLifecycleLog(t *testing.T, logPath string, agent *Agent) {
311→	t.Helper()
312→	data, err := os.ReadFile(logPath)
313→	if err != nil {
314→		t.Fatal(err)
315→	}
316→	lines := strings.Split(strings.TrimSpace(string(data)), "\n")
317→	wantHooks := []string{HookRunStart, HookTurnStart, HookTurnEnd, HookRunEnd}
318→	wantTypes := []int{1, 2, 3, 5}
319→	if len(lines) != len(wantHooks) {
320→		t.Fatalf("lifecycle calls = %d, want %d:\n%s", len(lines), len(wantHooks), data)
321→	}
322→	for i, line := range lines {
323→		parts := strings.SplitN(line, "\t", 2)
324→		wantArgs := "hooks github-actions " + wantHooks[i]
325→		if len(parts) != 2 || parts[0] != wantArgs {
326→			t.Fatalf("lifecycle call %d = %q, want args %q and payload", i, line, wantArgs)
327→		}
328→		event, err := agent.ParseHook(wantHooks[i], []byte(parts[1]))
329→		if err != nil {
330→			t.Fatal(err)
331→		}
332→		if event == nil || event.Type != wantTypes[i] || event.SessionID != v2SessionID {
333→			t.Fatalf("lifecycle event %d = %+v, want type %d/session %s", i, event, wantTypes[i], v2SessionID)
334→		}
335→		if wantHooks[i] == HookTurnStart && event.Prompt != v2Prompt {
336→			t.Errorf("turn-start prompt = %q, want %q", event.Prompt, v2Prompt)
337→		}
338→		if wantHooks[i] == HookTurnEnd && (event.ResponseMessage != v2Summary || event.Model != v2Model) {
339→			t.Errorf("turn-end response/model = %q/%q, want %q/%q", event.ResponseMessage, event.Model, v2Summary, v2Model)
340→		}
341→	}
342→}
